import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage } from '../../contexts/LanguageContext';
import { getApiUrl } from '../../utils/api';
import Logo from '../Common/Logo';
import LanguageSelector from '../Common/LanguageSelector';

const LoginForm = () => {
  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPasswordSetup, setShowPasswordSetup] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { login } = useAuth();
  const { t } = useLanguage();
  const navigate = useNavigate();

  const handleInitialLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    // Basic phone validation
    if (!phone.trim()) {
      setError('Please enter your phone number');
      setLoading(false);
      return;
    }

    const result = await login(phone, null, null); // No password initially

    if (result.success) {
      if (result.requiresPassword) {
        setShowPasswordSetup(true);
      } else {
        console.log('LoginForm: Login successful, navigating to dashboard');
        navigate('/', { replace: true });
      }
    } else {
      setError(result.error);
    }

    setLoading(false);
  };

  const handlePasswordLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (!password.trim()) {
      setError('Please enter your password');
      setLoading(false);
      return;
    }

    const result = await login(phone, password);

    if (result.success) {
      console.log('LoginForm: Password login successful, navigating to dashboard');
      navigate('/', { replace: true });
    } else {
      setError(result.error);
    }

    setLoading(false);
  };

  const handleSetPassword = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (!password.trim() || !confirmPassword.trim()) {
      setError('Please fill in all password fields');
      setLoading(false);
      return;
    }

    if (password !== confirmPassword) {
      setError('Passwords do not match');
      setLoading(false);
      return;
    }

    if (password.length < 6) {
      setError('Password must be at least 6 characters');
      setLoading(false);
      return;
    }

    try {
      const response = await fetch(getApiUrl('/auth/set-password'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          phone,
          password,
          confirm_password: confirmPassword
        }),
      });

      const data = await response.json();

      if (data.success) {
        // Now login with password
        const loginResult = await login(phone, password);
        if (loginResult.success) {
          console.log('LoginForm: Password setup and login successful, navigating to dashboard');
          navigate('/', { replace: true });
        } else {
          setError('Login failed after setting password');
        }
      } else {
        setError(data.detail || 'Failed to set password');
      }
    } catch (err) {
      setError('Failed to set password. Please try again.');
    }

    setLoading(false);
  };

  if (showPasswordSetup) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-green-50 py-12 px-4 sm:px-6 lg:px-8">
        <div className="max-w-md w-full space-y-8">
          <div>
            <Logo 
              size="large" 
              variant="login" 
              showText={true}
              className="mb-8"
            />
            <h2 className="mt-6 text-center text-3xl font-extrabold text-gray-900">
              {t('secureYourAccount', 'Secure Your Account')}
            </h2>
            <p className="mt-2 text-center text-sm text-gray-600">
              {t('setStrongPassword', 'Set a strong password to protect your account')}
            </p>
            <p className="mt-1 text-center text-xs text-gray-500">
              Your password must be at least 6 characters long
            </p>
          </div>

          <form className="mt-8 space-y-6" onSubmit={handleSetPassword}>
            <div className="space-y-4">
              <div>
                <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-2">
                  New Password
                </label>
                <input
                  id="password"
                  name="password"
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="appearance-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 rounded-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 focus:z-10 sm:text-sm"
                  placeholder="Enter your new password"
                />
              </div>

              <div>
                <label htmlFor="confirmPassword" className="block text-sm font-medium text-gray-700 mb-2">
                  Confirm Password
                </label>
                <input
                  id="confirmPassword"
                  name="confirmPassword"
                  type="password"
                  required
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className="appearance-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 rounded-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 focus:z-10 sm:text-sm"
                  placeholder="Confirm your password"
                />
              </div>
            </div>

            {error && (
              <div className="text-red-600 text-sm text-center bg-red-50 p-3 rounded-md">
                {error}
              </div>
            )}

            <div className="flex space-x-4">
              <button
                type="button"
                onClick={() => setShowPasswordSetup(false)}
                className="group relative w-full flex justify-center py-2 px-4 border border-gray-300 text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
              >
                Back
              </button>
              <button
                type="submit"
                disabled={loading}
                className="group relative w-full flex justify-center py-2 px-4 border border-transparent text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-50"
              >
                {loading ? 'Setting Password...' : 'Set Password & Login'}
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-green-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-md w-full space-y-8">
        {/* Language Selector - positioned at top right */}
        <div className="flex justify-end">
          <LanguageSelector />
        </div>

        <div>
          <Logo 
            size="large" 
            variant="login" 
            showText={true}
            className="mb-8"
          />
          <h2 className="mt-6 text-center text-3xl font-extrabold text-gray-900">
            {t('welcomeTo', 'Welcome to FixMate-SA')}
          </h2>
          <p className="mt-2 text-center text-sm text-gray-600">
            {t('southAfricasPremier', 'South Africa\'s Premier Service Platform')}
          </p>
          <p className="mt-1 text-center text-xs text-gray-500">
            {t('enterPhoneAndPassword', 'Enter your phone number and password to sign in')}
          </p>
        </div>

        <form className="mt-8 space-y-6" onSubmit={handlePasswordLogin}>
          <div className="space-y-4">
            <div>
              <label htmlFor="phone" className="block text-sm font-medium text-gray-700 mb-2">
                {t('phoneNumber', 'Phone Number')}
              </label>
              <input
                id="phone"
                name="phone"
                type="tel"
                required
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                className="appearance-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 rounded-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 focus:z-10 sm:text-sm"
                placeholder={t('enterPhone', 'Enter your phone number (e.g., +27821234567)')}
              />
            </div>

            <div>
              <label htmlFor="loginPassword" className="block text-sm font-medium text-gray-700 mb-2">
                {t('password', 'Password')}
              </label>
              <input
                id="loginPassword"
                name="loginPassword"
                type="password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="appearance-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 rounded-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 focus:z-10 sm:text-sm"
                placeholder={t('enterPassword', 'Enter your password')}
              />
            </div>
          </div>

          {error && (
            <div className="text-red-600 text-sm text-center bg-red-50 p-3 rounded-md">
              {error}
            </div>
          )}

          <div className="space-y-3">
            <button
              type="submit"
              disabled={loading}
              className="group relative w-full flex justify-center py-2 px-4 border border-transparent text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-50"
            >
              {loading ? t('loading', 'Signing in...') : t('signIn', 'Sign in')}
            </button>

            <div className="text-center">
              <span className="text-sm text-gray-600">or</span>
            </div>

            <button
              type="button"
              onClick={() => navigate('/signup')}
              className="group relative w-full flex justify-center py-2 px-4 border border-gray-300 text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
            >
              {t('dontHaveAccount', 'Don\'t have an account? Sign up')}
            </button>
          </div>

          <div className="text-center">
            <p className="text-xs text-gray-500">
              🔒 Your account is protected with secure password authentication
            </p>
          </div>
        </form>
      </div>
    </div>
  );
};

export default LoginForm;
